export function combatProfileMarkup(id,{E,esc,badge}){
 const p=E.championCombatProfile(id),contexts=[['skirmish','소규모 교전'],['teamfight','5:5 한타'],['pick','포착·갱킹'],['siege','공성·견제']];
 const examples=[{title:'잘 컸을 때 · 4 / 0 / 2',stats:{k:4,d:0,a:2}},{title:'성장이 막혔을 때 · 0 / 4 / 1',stats:{k:0,d:4,a:1}}];
 return `<section class="champion-combat-profile" aria-label="챔피언 성장과 교전 분석"><h3>성장 곡선 · 교전 특성</h3><div class="combat-tags">${E.combatLabels(id).map(x=>badge(x)).join('')}</div><p>${esc(p.note)}</p><div class="champion-phase-grid">${[5,14,24,34,45].map((minute,i)=>`<div><small>${minute}분</small><strong>${p.curve[i].toFixed(1)}<em> / 5</em></strong><span class="combat-meter"><i style="width:${p.curve[i]*20}%"></i></span></div>`).join('')}</div><div class="combat-context-grid">${contexts.map(([key,title])=>`<div><span>${title}</span><strong>${p[key].toFixed(1)} / 5</strong></div>`).join('')}</div><h4>킬·데스에 따른 변화</h4>${examples.map(x=>{const impact=E.championCombat(id,24,'teamfight',x.stats);return `<p class="combat-form-example"><strong>${x.title}</strong><span>${esc(impact.label)}</span></p>`;}).join('')}<p class="small muted">1~5점은 공식 스킬 설명을 해석한 게임용 상대 평가이며 실전 승률·패치 티어가 아닙니다. 실제 교전에는 참가 포지션·선수·골드·현재 킬/데스/어시스트가 함께 반영됩니다. 성장 시점은 시간과 전과로 근사하며 실제 레벨·아이템·스택을 전부 추적하지 않습니다.</p></section>`;
}
